  function toast(msg, level){ if(window.Forum && Forum.toast) Forum.toast(level || 'info', msg); else { var t=document.getElementById('mock-toast') || document.body.appendChild(Object.assign(document.createElement('div'),{id:'mock-toast'})); t.textContent=msg; t.className='mock-toast'; setTimeout(function(){t.textContent='';},2200); } }
  function ledger(kind, amount, detail){ state.ledger.unshift({ id:'l'+Date.now(), kind:kind, amount:amount, detail:detail, at:new Date().toLocaleString() }); state.ledger=state.ledger.slice(0,50); }
  function go(h){ history.pushState(null, '', h); render(); }
  function logged(target){ if(state.auth) return true; state.returnTo=target; save(); go('#login'); toast('请先登录后继续','warning'); return false; }
  function admin(target){ if(!logged(target)) return false; if(state.role!=='admin'){ go('#403'); return false; } return true; }
