  function setBusy(btn,label,fn){ if(btn.disabled)return; var old=btn.textContent;btn.disabled=true;btn.setAttribute('aria-busy','true');btn.textContent=label||'处理中…';setTimeout(function(){try{fn();}finally{if(btn.isConnected){btn.disabled=false;btn.removeAttribute('aria-busy');btn.textContent=old;}}},420); }
  function modal(title, body, actions){ var bd=document.createElement('div');bd.className='mock-modal-backdrop';bd.innerHTML='<section class="mock-modal" role="dialog" aria-modal="true"><header class="mock-modal__head"><h2>'+esc(title)+'</h2><button class="mock-modal__close" aria-label="关闭">×</button></header><div class="mock-modal__body">'+body+'</div><footer class="mock-modal__foot">'+(actions||button('关闭','','data-close-modal'))+'</footer></section>';document.body.appendChild(bd);bd.querySelector('.mock-modal__close').onclick=function(){bd.remove();};bd.querySelectorAll('[data-close-modal]').forEach(function(x){x.onclick=function(){bd.remove();};});return bd; }
  function showHome(){ main.style.display='block'; root.hidden=true; document.title='BBLBB · 首页'; }
  function postRow(p){ return '<a class="mock-row" href="#topic:'+esc(p.id)+'"><div class="mock-row__body"><strong>'+esc(p.title)+'</strong><p>'+esc(p.body.slice(0,120))+'</p><div class="mock-row__meta">'+pill(p.board)+' '+p.tags.split(',').map(function(t){return pill('#'+t.trim());}).join(' ')+'</div></div><span class="mock-pill">查看</span></a>'; }
  function renderArticles(){ var list=allPosts(); root.innerHTML=head('CONTENT','文章与讨论','可筛选、可发布、可进入详情的本地 Mock 内容',button('发布内容','primary','data-go="#publish:article"'))+card('内容流','<div class="mock-toolbar"><input class="mock-input" data-filter placeholder="按标题、正文或标签筛选"><select class="mock-select" data-board-filter><option value="">全部板块</option>'+boards.map(function(b){return '<option>'+b+'</option>';}).join('')+'</select>'+button('清除','', 'data-clear-filter')+'</div><div data-post-list>'+list.map(postRow).join('')+'</div><div class="mock-empty" hidden data-empty><strong>没有匹配内容</strong><p>修改关键词或清除筛选后再试。</p></div>'); bindPostFilter(); }
  function bindPostFilter(){ var input=root.querySelector('[data-filter]'), sel=root.querySelector('[data-board-filter]'), list=root.querySelector('[data-post-list]'), empty=root.querySelector('[data-empty]'); function apply(){ var q=(input.value||'').toLowerCase(), b=sel.value, visible=0;Array.from(list.children).forEach(function(row){var text=row.textContent.toLowerCase(), ok=(!q||text.indexOf(q)>=0)&&(!b||text.indexOf(b.toLowerCase())>=0);row.hidden=!ok;if(ok)visible++;});empty.hidden=visible>0;} input.oninput=apply;sel.onchange=apply;root.querySelector('[data-clear-filter]').onclick=function(){input.value='';sel.value='';apply();}; }
  function renderTopic(id){ var p=allPosts().find(function(x){return String(x.id)===String(id);});if(!p){return renderState('404','内容不存在','该内容可能已被删除。');} var locked=p.lock && !state.unlocked[p.id];var comments=state.comments[p.id]||[]; root.innerHTML=head('TOPIC',p.title,'评论、收藏、举报与受限内容均会保存本地 Mock 状态')+'<div class="mock-grid"><div>'+card('正文','<p>'+esc(p.body)+'</p><div class="mock-toolbar">'+button(state.likes[p.id]?'已点赞':'点赞','', 'data-like')+button(state.favorites.indexOf(p.id)>=0?'已收藏':'收藏','', 'data-favorite')+button('举报','danger','data-report')+'</div>'+(locked?'<div class="mock-note warn"><strong>受限内容</strong><p>'+ (p.lock==='paid'?'支付 10 B币后解锁。':'发表回复后解锁。') +'</p>'+button(p.lock==='paid'?'支付解锁':'去回复','primary',p.lock==='paid'?'data-paid-unlock':'data-focus-reply')+'</div>':'<div class="mock-note"><strong>已解锁内容</strong><p>这里展示本地 Mock 受限正文。正式环境必须由服务端授权返回。</p></div>') )+card('回复','<textarea class="mock-textarea" data-comment placeholder="写下你的回复…"></textarea><div class="mock-toolbar">'+button('保存草稿','','data-comment-draft')+button('发表回复','primary','data-comment-submit')+'</div><div data-comments>'+comments.map(function(c){return '<div class="mock-row"><div class="mock-row__body"><strong>'+esc(c.author)+'</strong><p>'+esc(c.text)+'</p></div>'+button('引用','sm','data-quote="'+esc(c.text)+'"')+'</div>';}).join('')+'</div>')+'</div><aside class="mock-side">'+card('本地状态','<div class="mock-stats"><div class="mock-stat"><small>B币</small><strong>'+state.coins+'</strong></div><div class="mock-stat"><small>收藏</small><strong>'+state.favorites.length+'</strong></div><div class="mock-stat"><small>回复</small><strong>'+comments.length+'</strong></div></div>')+'</aside></div>'; root.querySelector('[data-like]').onclick=function(){state.likes[p.id]=!state.likes[p.id];save();renderTopic(id);};root.querySelector('[data-favorite]').onclick=function(){var n=state.favorites.indexOf(p.id);if(n<0)state.favorites.push(p.id);else state.favorites.splice(n,1);save();renderTopic(id);};root.querySelector('[data-report]').onclick=function(){openReport(p.id);};root.querySelectorAll('[data-quote]').forEach(function(b){b.onclick=function(){var t=root.querySelector('[data-comment]');t.value='> '+b.getAttribute('data-quote')+'\n\n';t.focus();};});root.querySelector('[data-comment-draft]').onclick=function(){state.draft.comment=root.querySelector('[data-comment]').value;save();toast('回复草稿已保存');};root.querySelector('[data-comment-submit]').onclick=function(){var v=root.querySelector('[data-comment]').value.trim();if(!v){toast('回复内容不能为空','warning');return;}setBusy(this,'发布中…',function(){if(!state.comments[p.id])state.comments[p.id]=[];state.comments[p.id].push({author:'Chaos',text:v});if(p.lock==='reply')state.unlocked[p.id]=true;ledger('reply',1,'主题回复');save();renderTopic(id);toast('回复已发布');});};var paid=root.querySelector('[data-paid-unlock]');if(paid)paid.onclick=function(){modal('确认支付','<p>当前余额：<strong>'+state.coins+' B币</strong>；本次将扣除 10 B币。</p>',''+button('取消','','data-close-modal')+button('确认支付','primary','data-confirm-paid'));document.querySelector('[data-confirm-paid]').onclick=function(){if(state.coins<10){toast('B币不足','warning');return;}state.coins-=10;state.unlocked[p.id]=true;ledger('unlock',-10,'受限内容解锁');save();document.querySelector('.mock-modal-backdrop').remove();renderTopic(id);toast('已解锁');};};var focus=root.querySelector('[data-focus-reply]');if(focus)focus.onclick=function(){root.querySelector('[data-comment]').focus();}; }
  function openReport(id){ modal('提交举报','<label>原因<select class="mock-select" data-report-kind><option value="spam">垃圾广告</option><option value="abuse">人身攻击</option><option value="illegal">违法违规</option></select></label><label>补充说明<textarea class="mock-textarea" data-report-note></textarea></label>',''+button('取消','','data-close-modal')+button('提交','danger','data-confirm-report'));document.querySelector('[data-confirm-report]').onclick=function(){var rid='R-'+Date.now().toString().slice(-5);state.reports[rid]={status:'pending',target:id,kind:document.querySelector('[data-report-kind]').value,note:document.querySelector('[data-report-note]').value,timeline:['用户提交举报 · 刚刚']};state.notifications.unshift({id:'n'+Date.now(),type:'system',title:'举报已受理',target:'#appeals',unread:true});save();document.querySelector('.mock-modal-backdrop').remove();toast('举报已提交 · '+rid);}; }
  function renderPublish(){ var d=state.draft;root.innerHTML=head('CREATE','发布内容','Mock 编辑器支持草稿、附件、可见性、定时与视频引用',button('草稿管理','','data-go="#drafts"'))+'<div class="mock-grid"><div>'+card('编辑器','<div class="mock-toolbar"><select class="mock-select" data-type><option value="article">文章</option><option value="topic">讨论</option></select><select class="mock-select" data-board><option value="">选择板块</option>'+boards.map(function(b){return '<option '+(d.board===b?'selected':'')+'>'+b+'</option>';}).join('')+'</select></div><label>标题<input class="mock-input" data-title value="'+esc(d.title||'')+'"></label><label>标签（逗号分隔）<input class="mock-input" data-tags value="'+esc(d.tags||'')+'"></label><label>摘要<textarea class="mock-textarea" data-summary>'+esc(d.summary||'')+'</textarea></label><label>正文<textarea class="mock-textarea" data-body>'+esc(d.body||'')+'</textarea></label><div class="mock-toolbar">'+button('编辑','','data-mode="edit"')+button('预览','','data-mode="preview"')+button('分屏','','data-mode="split"')+'</div><div class="mock-ai-output" data-preview hidden></div>')+card('附件与视频','<div class="mock-file"><strong>附件</strong><input type="file" data-file><small>Mock 限制：10 MB。选择后进入本地上传队列。</small></div><div data-attachments></div><div class="mock-video-panel"><label>视频 URL<input class="mock-input" data-video-url placeholder="https://example.com/video"></label>'+button('安全解析','', 'data-video-resolve')+'<div class="wf-video-result" data-video-result hidden></div></div>')+card('发布策略','<div class="mock-toolbar"><select class="mock-select" data-visibility><option value="public">公开</option><option value="reply">回复解锁</option><option value="paid">付费解锁</option></select><input class="mock-input" data-price type="number" min="1" value="'+(d.price||10)+'" placeholder="付费价格"><input class="mock-input" data-schedule type="datetime-local" value="'+esc(d.schedule||'')+'"></div><label class="mock-check"><input type="checkbox" data-allow-replies '+(d.allowReplies!==false?'checked':'')+'>允许回复</label><div class="mock-toolbar">'+button('保存草稿','','data-save-draft')+button('提交审核','','data-submit-review')+button('发布','primary','data-publish')+'</div></div>')+'</div><aside class="mock-side">'+card('发布状态','<div class="mock-note">本页所有操作均为 Mock；上传、视频解析和发布不会访问 /api/v1。</div>')+card('AI 助手',''+button('格式化草稿','','data-ai-format')+button('生成摘要','','data-ai-summary')+'<div data-ai-output></div>')+'</aside></div>';var fields=['title','tags','summary','body','board','visibility','price','schedule'];function capture(){fields.forEach(function(k){var el=root.querySelector('[data-'+k+']');if(el)d[k]=el.value;});d.type=root.querySelector('[data-type]').value;d.allowReplies=root.querySelector('[data-allow-replies]').checked;save();}root.querySelectorAll('input,textarea,select').forEach(function(el){el.addEventListener('input',capture);el.addEventListener('change',capture);});root.querySelectorAll('[data-mode]').forEach(function(b){b.onclick=function(){capture();var p=root.querySelector('[data-preview]');p.hidden=false;p.textContent=d.body||'暂无正文';if(b.getAttribute('data-mode')==='edit')p.hidden=true;};});root.querySelector('[data-file]').onchange=function(){var f=this.files[0];if(!f)return;if(f.size>10*1024*1024){toast('附件超过 10 MB','warning');this.value='';return;}state.attachments.push({id:'a'+Date.now(),name:f.name,size:f.size,status:'uploading'});save();renderPublish();setTimeout(function(){var a=state.attachments.find(function(x){return x.status==='uploading';});if(a){a.status='ready';save();if(currentHash().startsWith('#publish'))renderPublish();}},500);};function attachView(){var host=root.querySelector('[data-attachments]');host.innerHTML=state.attachments.map(function(a){return '<div class="mock-attachment"><span>📎</span><div class="mock-line grow"><span class="grow">'+esc(a.name)+'<small>'+Math.round(a.size/1024)+' KB · '+esc(a.status)+'</small></span>'+button('移除','sm','data-remove-attachment="'+a.id+'"')+'</div></div>';}).join('');host.querySelectorAll('[data-remove-attachment]').forEach(function(b){b.onclick=function(){state.attachments=state.attachments.filter(function(a){return a.id!==b.getAttribute('data-remove-attachment');});save();renderPublish();};});}attachView();root.querySelector('[data-video-resolve]').onclick=function(){var u=root.querySelector('[data-video-url]').value.trim(),out=root.querySelector('[data-video-result]');if(!/^https:\/\//i.test(u)){out.hidden=false;out.textContent='仅允许 HTTPS 视频链接。';return;}if(/localhost|127\.0\.0\.1|10\.|192\.168\./.test(u)){out.hidden=false;out.textContent='已拒绝内网地址（Mock SSRF 防护）。';return;}state.videos.push({url:u,status:'resolved'});save();out.hidden=false;out.textContent='解析成功：将作为结构化引用保存，不内嵌不可信 HTML。';};root.querySelector('[data-ai-format]').onclick=function(){capture();var out=root.querySelector('[data-ai-output]');out.textContent='格式化任务处理中…';setTimeout(function(){d.body=(d.body||'').replace(/\s+$/,'')+'\n\n> AI 格式化建议（Mock）';save();out.textContent='格式化建议已生成，可继续编辑或保存草稿。';},450);};root.querySelector('[data-ai-summary]').onclick=function(){capture();root.querySelector('[data-ai-output]').textContent='摘要：'+(d.body||'暂无内容').replace(/\s+/g,' ').slice(0,80)+'…';};root.querySelector('[data-save-draft]').onclick=function(){capture();toast('草稿已保存');};function validate(){capture();if(!d.title||!d.board||!d.body){toast('标题、板块和正文为必填项','warning');return false;}return true;}root.querySelector('[data-submit-review]').onclick=function(){if(!validate())return;state.posts.unshift({id:'p'+Date.now(),title:d.title,board:d.board,body:d.body,tags:d.tags,status:'pending_review'});state.draft={};save();toast('已提交审核');go('#drafts');};root.querySelector('[data-publish]').onclick=function(){if(!validate())return;var id='p'+Date.now();state.posts.unshift({id:id,title:d.title,board:d.board,body:d.body,tags:d.tags,lock:d.visibility==='public'?'':d.visibility,status:d.schedule?'scheduled':'published'});state.draft={};ledger('publish',1,'发布内容');save();toast(d.schedule?'已安排定时发布':'发布成功');go('#topic:'+id);}; }
  function renderDrafts(){var entries=(state.posts||[]).filter(function(p){return p.status==='pending_review'||p.status==='scheduled';});root.innerHTML=head('CREATE','草稿与审核','本地草稿、审核中和定时发布内容')+card('当前草稿','<div class="mock-toolbar">'+button('继续编辑','primary','data-go="#publish"')+button('清空草稿','danger','data-clear-draft')+'</div><p class="wf-muted">'+(state.draft.title?esc(state.draft.title):'尚未保存标题')+'</p>')+card('待处理内容','<div class="mock-list">'+(entries.length?entries.map(function(p){return '<div class="mock-row"><div class="mock-row__body"><strong>'+esc(p.title)+'</strong><p>'+esc(p.status==='scheduled'?'定时发布':'审核中')+' · '+esc(p.board)+'</p></div>'+button('继续编辑','', 'data-edit-post="'+p.id+'"')+button('删除','danger','data-delete-post="'+p.id+'"')+'</div>';}).join(''):'<div class="mock-empty"><strong>暂无待处理内容</strong><p>发布或提交审核后的内容会显示在这里。</p></div>')+'</div>');root.querySelector('[data-go]').onclick=function(){go('#publish');};root.querySelector('[data-clear-draft]').onclick=function(){state.draft={};save();renderDrafts();};root.querySelectorAll('[data-edit-post]').forEach(function(b){b.onclick=function(){var p=state.posts.find(function(x){return x.id===b.getAttribute('data-edit-post');});if(p){state.draft=Object.assign({},p);save();go('#publish');}};});root.querySelectorAll('[data-delete-post]').forEach(function(b){b.onclick=function(){state.posts=state.posts.filter(function(p){return p.id!==b.getAttribute('data-delete-post');});save();renderDrafts();toast('内容已删除');};}); }
  function renderNotifications(){var list=state.notifications||[];root.innerHTML=head('INBOX','通知中心','本地已读、筛选和来源跳转')+card('通知','<div class="mock-tabs"><button class="active" data-nfilter="all">全部</button><button data-nfilter="unread">未读</button><button data-nfilter="reply">回复</button><button data-nfilter="system">系统</button></div><div class="mock-list" data-notify-list>'+list.map(function(n){return '<a class="mock-row" href="'+esc(n.target||'#home')+'" data-notification="'+n.id+'"><div class="mock-row__body"><strong>'+esc(n.title)+'</strong><p>'+esc(n.detail||'刚刚')+'</p></div>'+pill(n.unread?'未读':'已读',n.unread?'warn':'')+'</a>';}).join('')+'</div>',''+button('全部已读','','data-read-all'));function filter(){var mode=root.querySelector('.mock-tabs .active').getAttribute('data-nfilter');root.querySelectorAll('[data-notification]').forEach(function(row){var n=list.find(function(x){return x.id===row.getAttribute('data-notification');});row.hidden=mode==='all'?false:mode==='unread'?!n.unread:n.type!==mode;});}root.querySelectorAll('[data-nfilter]').forEach(function(b){b.onclick=function(){root.querySelectorAll('[data-nfilter]').forEach(function(x){x.classList.remove('active');});b.classList.add('active');filter();};});root.querySelector('[data-read-all]').onclick=function(){list.forEach(function(n){n.unread=false;});save();renderNotifications();toast('通知已全部标记为已读');};root.querySelectorAll('[data-notification]').forEach(function(row){row.onclick=function(){var n=list.find(function(x){return x.id===row.getAttribute('data-notification');});if(n){n.unread=false;save();}go(row.getAttribute('href'));};}); }
  function renderBilling(){root.innerHTML=head('ACCOUNT','下载账单','下载授权、短链与扣点 Mock 工作流')+card('授权与账单','<div class="mock-stats"><div class="mock-stat"><small>B币</small><strong>'+state.coins+'</strong></div><div class="mock-stat"><small>有效授权</small><strong>3</strong></div><div class="mock-stat"><small>本月下载</small><strong>24</strong></div></div><div class="mock-list"><div class="mock-row"><div class="mock-row__body"><strong>architecture.pdf</strong><p>等级免费 · 授权有效至明天</p></div>'+button('生成短链','', 'data-sign-link')+'</div><div class="mock-row"><div class="mock-row__body"><strong>report.zip</strong><p>扣除 10 积分 · 已授权</p></div>'+button('再次下载','', 'data-download')+'</div></div>');root.querySelector('[data-sign-link]').onclick=function(){setBusy(this,'签名中…',function(){toast('已生成临时下载链接 · 10 分钟有效');});};root.querySelector('[data-download]').onclick=function(){setBusy(this,'准备中…',function(){toast('下载已开始（Mock）');});}; }

  function renderAdmin(route){if(!admin(route))return;var title=(route||'#admin').replace('#admin','管理后台')||'管理后台';root.innerHTML=head('ADMIN',title,'后台 Mock 数据，支持筛选、批量操作、确认和审计记录')+'<div class="mock-admin-shell"><aside class="mock-admin-side"><strong>BBLBB Admin</strong><small>运营</small><a href="#admin" class="active">仪表盘</a><a href="#admin-reports">举报审核</a><a href="#admin-points">积分账本</a><a href="#admin-themes">主题管理</a><a href="#admin-plugins">插件管理</a><a href="#admin-ai">AI 任务</a><a href="#admin-video">视频策略</a><a href="#admin-storage">文件存储</a><a href="#admin-marketplace">市场交易</a><a href="#admin-audit">审计日志</a></aside><section class="mock-admin-main" data-admin-slot></section></div>';var slot=root.querySelector('[data-admin-slot]');if(route==='#admin-reports'){renderAdminReports(slot);return;}if(route==='#admin-points'){renderAdminPoints(slot);return;}if(route==='#admin-themes'){renderAdminThemes(slot);return;}if(route==='#admin-plugins'){renderAdminPlugins(slot);return;}if(route==='#admin-ai'){renderAdminAI(slot);return;}if(route==='#admin-video'){renderAdminVideo(slot);return;}if(route==='#admin-storage'){renderAdminStorage(slot);return;}if(route==='#admin-marketplace'){renderAdminMarketplace(slot);return;}if(route==='#admin-audit'){renderAdminAudit(slot);return;}slot.innerHTML=card('运营总览','<div class="mock-stats"><div class="mock-stat"><small>待审核举报</small><strong>'+Object.keys(state.reports).length+'</strong></div><div class="mock-stat"><small>Mock 队列</small><strong>'+state.aiTasks.length+'</strong></div><div class="mock-stat"><small>本地账本</small><strong>'+state.ledger.length+'</strong></div></div><div class="mock-note warn">生产邮件 sender 尚未接入。该页面不代表 /readyz、metrics 或后台 API 已连接。</div>')+card('快捷操作','<div class="mock-toolbar">'+button('处理举报','primary','data-go="#admin-reports"')+button('调整积分','','data-go="#admin-points"')+button('切换普通成员','','data-role-toggle')+'</div>');slot.querySelectorAll('[data-go]').forEach(function(b){b.onclick=function(){go(b.getAttribute('data-go'));};});slot.querySelector('[data-role-toggle]').onclick=function(){state.role=state.role==='admin'?'member':'admin';save();toast(state.role==='admin'?'已切换管理员':'已切换普通成员');};}
  function renderAdminReports(slot){var entries=Object.keys(state.reports).map(function(id){return Object.assign({id:id},state.reports[id]);});slot.innerHTML=card('举报与审核','<div class="mock-toolbar"><input class="mock-input" data-report-filter placeholder="搜索单号或原因">'+button('批量标为处理中','','data-bulk-progress')+'</div><div class="mock-bulkbar" hidden data-bulkbar><strong data-selected-count>0</strong> 项已选中 '+button('批量关闭','danger','data-bulk-close')+button('取消','','data-bulk-cancel')+'</div><div class="mock-table-wrap"><table class="mock-table"><thead><tr><th><input type="checkbox" data-select-all></th><th>单号</th><th>状态</th><th>原因</th><th>时间线</th><th>操作</th></tr></thead><tbody>'+entries.map(function(r){return '<tr data-report-row="'+esc(r.id)+'"><td><input type="checkbox" data-report-select="'+esc(r.id)+'"></td><td>'+esc(r.id)+'</td><td>'+pill(r.status,r.status==='resolved'?'ok':'warn')+'</td><td>'+esc(r.reason||'待补充')+'</td><td>'+esc((r.timeline||[]).slice(-1)[0]||'—')+'</td><td>'+button('处理','sm','data-handle-report="'+esc(r.id)+'"')+'</td></tr>';}).join('')+'</tbody></table></div>');var selected=[];function sync(){var bar=slot.querySelector('[data-bulkbar]');bar.hidden=!selected.length;slot.querySelector('[data-selected-count]').textContent=selected.length;};slot.querySelectorAll('[data-report-select]').forEach(function(b){b.onchange=function(){var id=b.getAttribute('data-report-select');selected=b.checked?selected.concat(id):selected.filter(function(x){return x!==id;});sync();};});slot.querySelector('[data-select-all]').onchange=function(){var checked=this.checked;selected=[];slot.querySelectorAll('[data-report-select]').forEach(function(x){x.checked=checked;if(checked)selected.push(x.getAttribute('data-report-select'));});sync();};slot.querySelector('[data-bulk-close]').onclick=function(){selected.forEach(function(id){state.reports[id].status='resolved';state.reports[id].timeline.push('批量关闭 · 刚刚');});save();renderAdminReports(slot);toast('批量操作已完成');};slot.querySelector('[data-bulk-cancel]').onclick=function(){selected=[];slot.querySelectorAll('[data-report-select]').forEach(function(x){x.checked=false;});sync();};slot.querySelector('[data-bulk-progress]').onclick=function(){selected=Object.keys(state.reports);sync();};slot.querySelectorAll('[data-handle-report]').forEach(function(b){b.onclick=function(){var id=b.getAttribute('data-handle-report');modal('处理 '+id,'<label>处理原因<textarea class="mock-textarea" data-case-reason></textarea></label><label>操作<select class="mock-select" data-case-action><option value="hide">隐藏内容</option><option value="mute">禁言 7 天</option><option value="reject">驳回举报</option></select></label>',''+button('取消','','data-close-modal')+button('确认处理','danger','data-confirm-case'));document.querySelector('[data-confirm-case]').onclick=function(){var reason=document.querySelector('[data-case-reason]').value.trim();if(!reason){toast('处理原因必填','warning');return;}state.reports[id].status='resolved';state.reports[id].reason=reason;state.reports[id].timeline.push(document.querySelector('[data-case-action]').value+' · '+reason+' · 刚刚');save();document.querySelector('.mock-modal-backdrop').remove();renderAdminReports(slot);toast('案件已处理');};};});}
  function renderAdminPoints(slot){slot.innerHTML=card('积分与货币','<div class="mock-stats"><div class="mock-stat"><small>B币余额</small><strong>'+state.coins+'</strong></div><div class="mock-stat"><small>经验</small><strong>'+state.exp+'</strong></div><div class="mock-stat"><small>账本条目</small><strong>'+state.ledger.length+'</strong></div></div><div class="mock-toolbar"><input class="mock-input" data-adjust-amount type="number" value="50"><select class="mock-select" data-adjust-kind><option value="coins">B币</option><option value="exp">经验</option></select><input class="mock-input" data-adjust-reason placeholder="调整原因（必填）">'+button('调整积分','primary','data-adjust')+'</div><div class="mock-table-wrap"><table class="mock-table"><thead><tr><th>时间</th><th>类型</th><th>变化</th><th>来源</th></tr></thead><tbody>'+state.ledger.map(function(x){return '<tr><td>'+esc(x.at)+'</td><td>'+esc(x.kind)+'</td><td>'+esc(x.amount)+'</td><td>'+esc(x.detail)+'</td></tr>';}).join('')+'</tbody></table></div>');slot.querySelector('[data-adjust]').onclick=function(){var amount=Number(slot.querySelector('[data-adjust-amount]').value)||0,reason=slot.querySelector('[data-adjust-reason]').value.trim(),kind=slot.querySelector('[data-adjust-kind]').value;if(!amount||!reason){toast('数额和原因必填','warning');return;}modal('二次确认','<p>历史流水不可删除，仅可创建补偿记录。</p><p>将调整 '+amount+' '+kind+'，原因：'+esc(reason)+'</p>',''+button('取消','','data-close-modal')+button('确认调整','primary','data-final-adjust'));document.querySelector('[data-final-adjust]').onclick=function(){state[kind]+=amount;ledger('admin_adjust',amount,reason);save();document.querySelector('.mock-modal-backdrop').remove();renderAdminPoints(slot);toast('调整已记录');};};}
  function renderAdminThemes(slot){slot.innerHTML=card('主题管理','<div class="mock-grid"><div class="mock-card"><div class="mock-card__body"><strong>默认主题</strong><p class="wf-muted">数据型主题，可立即预览。</p>'+button('预览','','data-preview-theme="light"')+' '+button('应用','primary','data-apply-theme="light"')+'</div></div><div class="mock-card"><div class="mock-card__body"><strong>暗夜蓝</strong><p class="wf-muted">数据型主题，可立即预览。</p>'+button('预览','','data-preview-theme="dark"')+' '+button('应用','primary','data-apply-theme="dark"')+'</div></div><div class="mock-card"><div class="mock-card__body"><strong>代码型主题</strong><p class="wf-muted">需要重新构建部署。</p>'+pill('需部署','warn')+'</div></div></div>');slot.querySelectorAll('[data-preview-theme],[data-apply-theme]').forEach(function(b){b.onclick=function(){var mode=b.getAttribute('data-preview-theme')||b.getAttribute('data-apply-theme');document.documentElement.setAttribute('data-theme',mode);state.theme=mode;save();toast(b.hasAttribute('data-apply-theme')?'主题已应用':'主题预览中');};});}
