  function renderAdminAI(slot){var tasks=state.aiTasks;slot.innerHTML=card('AI 任务与同意','<div class="mock-toolbar">'+button('创建格式化任务','primary','data-ai-new')+button('切换同意状态','','data-ai-consent')+'</div><div class="mock-note">Mock 仅展示异步任务状态；正式环境需数据同意、脱敏、预算与版本冲突控制。</div><div>'+tasks.map(function(t){return '<div class="mock-row"><div class="mock-row__body"><strong>'+esc(t.kind)+'</strong><p>'+esc(t.status)+' · '+esc(t.output||'等待处理')+'</p></div>'+button(t.status==='running'?'取消':'查看','sm','data-ai-action="'+t.id+'"')+'</div>';}).join('')+'</div>');slot.querySelector('[data-ai-new]').onclick=function(){var t={id:'ai'+Date.now(),kind:'格式化草稿',status:'running'};tasks.unshift(t);save();renderAdminAI(slot);setTimeout(function(){t.status='completed';t.output='建议：使用二级标题拆分段落，并保留代码块语言。';save();if(currentHash()==='#admin-ai')renderAdminAI(slot);},600);};slot.querySelector('[data-ai-consent]').onclick=function(){state.toggles.aiConsent=!state.toggles.aiConsent;save();toast(state.toggles.aiConsent?'已同意 AI 辅助':'已撤销 AI 同意');};slot.querySelectorAll('[data-ai-action]').forEach(function(b){b.onclick=function(){var t=tasks.find(function(x){return x.id===b.getAttribute('data-ai-action');});if(t&&t.status==='running'){t.status='cancelled';save();renderAdminAI(slot);toast('任务已取消');}};});}
